edits.newText:
test('makeBricks: full, all-alive grid at start', () => {
  const bricks = makeBricks(1);
  assert.equal(bricks.length, BRICK_ROWS * BRICK_COLS);
  assert.ok(bricks.every((b) => b.alive));
  assert.ok(bricks.every((b) => b.x >= 0 && b.x + b.w <= WIDTH));
});

// --- Brick bounce (#1) ----------------------------------------------------
// The ball must be deflected by a brick, not plow through it: per-face bounce
// (flip vy on top/bottom, vx on side), corner hits flip both, the ball is
// pushed back out, a seam hit bounces exactly once, and a fast ball is caught
// by a sweep (no tunnelling).

// A minimal state around a single brick: the ball, one live brick, and the
// score/combo fields brickHit touches.
function brickState(ball, brick) {
  return {
    ball,
    bricks: [brick],
    score: 0,
    combo: 0,
  };
}

function singleBrick(x = 100, y = 100, w = 72, h = 20) {
  return { x, y, w, h, row: 0, alive: true, points: 100 };
}

const UP = -1;
const DOWN = 1;
const LEFT = -1;
const RIGHT = 1;

// step: the ball falls onto the top of a brick and bounces back up (#1).
test('step: ball bounces off the top face of a brick', () => {
  const state = createState(1);
  state.ball = { x: 136, y: 80, r: 7, vx: 0, vy: 300 }; // above the brick
  state.bricks = [singleBrick()]; // top edge at y=100

  step(state, 1 / 60); // 5 px down: ball now overlaps the brick

  assert.equal(state.bricks[0].alive, false, 'brick should be destroyed');
  assert.equal(Math.sign(state.ball.vy), UP, 'ball should rebound upward');
});

// step: a near-horizontal shot into the side of a brick flips vx, not vy.
test('step: ball bounces off the side face of a brick', () => {
  const state = createState(1);
  state.ball = { x: 80, y: 110, r: 7, vx: 300, vy: 0 }; // left of the brick
  state.bricks = [singleBrick()]; // left edge at x=100

  step(state, 1 / 60);

  assert.equal(state.bricks[0].alive, false);
  assert.equal(Math.sign(state.ball.vx), LEFT, 'horizontal velocity should flip');
  assert.equal(Math.sign(state.ball.vy), 0, 'vertical velocity must stay untouched');
});

// step: the ball comes up from below and is deflected back down.
test('step: ball bounces off the bottom face of a brick', () => {
  const state = createState(1);
  state.ball = { x: 136, y: 140, r: 7, vx: 0, vy: -300 }; // below the brick
  state.bricks = [singleBrick()]; // bottom edge at y=120

  step(state, 1 / 60);

  assert.equal(state.bricks[0].alive, false);
  assert.equal(Math.sign(state.ball.vy), DOWN, 'ball should rebound downward');
});

// brickHit: a diagonal shot into a corner flips BOTH components.
test('brickHit: corner hit flips both velocity components', () => {
  const brick = singleBrick(); // corner at (100,100)
  const ball = { x: 83, y: 83, r: 7, vx: 100, vy: 100 };
  const state = brickState(ball, brick);

  // Path (83,83) -> (93,93): exactly through the expanded-box corner.
  const destroyed = brickHit(state, 83, 83);

  assert.equal(destroyed, 1);
  assert.equal(Math.sign(ball.vx), LEFT);
  assert.equal(Math.sign(ball.vy), UP);
});

// brickHit: the ball must be pushed OUT of the brick, otherwise it stays
// overlapping and the bounce would re-trigger forever (sticky bounce).
test('brickHit: ball is pushed out of the brick (no sticky overlap)', () => {
  const brick = singleBrick();
  const ball = { x: 136, y: 96, r: 7, vx: 0, vy: 300 };
  const state = brickState(ball, brick);

  brickHit(state, 136, 80); // swept down into the top face

  assert.ok(
    ball.y + ball.r <= brick.y,
    'ball must end up entirely above the brick'
  );
});

// brickHit: the grid gap is 8 px and the ball is 14 px across, so a ball
// straddling a seam overlaps two bricks in the same pass. The bounce must
// apply exactly once: flipping vy twice would cancel out and the ball would
// plow straight through.
test('brickHit: seam between two bricks bounces exactly once', () => {
  const left = singleBrick(100, 100); // right edge at 172
  const right = singleBrick(180, 100); // left edge at 180 (8 px gap)
  const ball = { x: 176, y: 90, r: 7, vx: 0, vy: 300 }; // straddling the seam
  const state = brickState(ball, [left, right]);

  const destroyed = brickHit(state, 176, 80);

  assert.equal(destroyed, 2, 'both bricks touched by the seam should break');
  assert.equal(Math.sign(ball.vy), UP, 'vy flipped exactly once');
  assert.equal(ball.vx, 0, 'vx untouched by a pure vertical shot');
});

// brickHit: detection is discrete; a fast ball can jump across a brick in one
// step. The path must be swept between the two positions, not just tested at
// the end point.
test('brickHit: sweep catches a tunnelling ball', () => {
  const brick = singleBrick(); // y from 100 to 120
  const ball = { x: 136, y: 80, r: 7, vx: 0, vy: 1000 };
  const state = brickState(ball, brick);

  // 50 px in one move: lands at y=130, BELOW the brick, no end-point overlap.
  const destroyed = brickHit(state, 136, 80);

  assert.equal(destroyed, 1, 'fast ball must still hit the brick');
  assert.equal(Math.sign(ball.vy), UP, 'and bounce back up');
});

// brickHit: every brick touched in one pass breaks and scores (combo applied
// per brick, like the old inline logic did).
test('brickHit: destroys and scores every brick touched in the pass', () => {
  const a = singleBrick(100, 100);
  const b = singleBrick(180, 100);
  const ball = { x: 176, y: 90, r: 7, vx: 0, vy: 300 };
  const state = brickState(ball, [a, b]);

  brickHit(state, 176, 80);

  assert.equal(state.score, 250); // 100 * 1.5 + 100 * 2.0
  assert.equal(state.combo, 2);
});

