// neon.js — NÉON, a minimalist brick breaker (zero dependencies).
//
// Game logic lives in the pure functions below (tested under `node --test`);
// only `boot()` touches the DOM. Nothing runs on import, so the logic can be
// imported from the tests without a browser.

import { palette, brickColor } from './theme.js';
import { createGlowMap, drawGlow, GLOW_W, GLOW_H } from './bloom.js';

// --- Axis convention -------------------------------------------------------

// Screen coordinates, as the canvas defines them: the origin is the TOP-LEFT
// corner and **Y GROWS DOWNWARD**. So `y = 0` is the ceiling, `y = HEIGHT` the
// line through which the ball is lost, and a ball climbing toward the bricks
// has a NEGATIVE `vy`. Every sign in this file follows from that single
// choice — the launch velocity, each bounce, and the paddle test `vy > 0`.
//
// The constants below name the sign a velocity component takes per heading.
// Assert against them rather than against a bare `-1` / `1`: a test reading
// `Math.sign(ball.vy) === UP` states its intent, where a hard-coded `-1` only
// states an arithmetic fact and quietly means the opposite if the convention
// ever flips.
//
//   UP    (-1)  toward the ceiling and the bricks
//   DOWN  (+1)  toward the paddle and the loss line
//   LEFT  (-1)  toward x = 0
//   RIGHT (+1)  toward x = WIDTH

export const UP = -1;
export const DOWN = 1;
export const LEFT = -1;
export const RIGHT = 1;

// --- Field constants -------------------------------------------------------

export const WIDTH = 640;
export const HEIGHT = 480;

export const PADDLE_W = 96;
export const PADDLE_H = 12;
export const PADDLE_Y = HEIGHT - 32;

export const BALL_R = 7;

export const BRICK_ROWS = 5;
export const BRICK_COLS = 8;
export const BRICK_W = 72;
export const BRICK_H = 20;
export const BRICK_GAP = 8;
export const BRICK_TOP = 48;

const STORAGE_KEY = 'neon.best';

// --- State construction ----------------------------------------------------

// Builds the brick grid for a given level.
// The higher the level, the more points bricks are worth.
export function makeBricks(level = 1) {
  const bricks = [];
  const offsetX = (WIDTH - (BRICK_COLS * (BRICK_W + BRICK_GAP) - BRICK_GAP)) / 2;
  for (let row = 0; row < BRICK_ROWS; row++) {
    for (let col = 0; col < BRICK_COLS; col++) {
      bricks.push({
        x: offsetX + col * (BRICK_W + BRICK_GAP),
        y: BRICK_TOP + row * (BRICK_H + BRICK_GAP),
        w: BRICK_W,
        h: BRICK_H,
        row,
        alive: true,
        points: (BRICK_ROWS - row) * 10 * level,
      });
    }
  }
  return bricks;
}

// Ball speed as a function of the level (ramps up with each level).
export function ballSpeed(level = 1) {
  return 260 + (level - 1) * 90;
}

// Creates a fresh game state.
export function createState(level = 1) {
  const speed = ballSpeed(level);
  return {
    level,
    lives: 3,
    score: 0,
    combo: 0,
    best: 0,
    running: false,
    paddle: { x: (WIDTH - PADDLE_W) / 2, y: PADDLE_Y, w: PADDLE_W, h: PADDLE_H },
    ball: { x: WIDTH / 2, y: PADDLE_Y - BALL_R - 2, r: BALL_R, vx: speed * 0.5, vy: -speed },
    bricks: makeBricks(level),
  };
}

// --- Collision (tested primitive) ------------------------------------------

// True if the ball (circle approximated by its box) overlaps the brick.
// Simple AABB test: it only says WHETHER the ball and the brick overlap, not
// WHICH face was hit. The actual bounce lives in brickHit() (#1).
export function collides(ball, brick) {
  return (
    ball.x + ball.r > brick.x &&
    ball.x - ball.r < brick.x + brick.w &&
    ball.y + ball.r > brick.y &&
    ball.y - ball.r < brick.y + brick.h
  );
}

// --- Brick collision (#1): sweep, single bounce, push-out -----------------

// Extra room the ball is pushed out of a brick after a bounce, so the very
// next frame cannot re-detect the same contact (sticky bounce).
const PUSH_OUT = 1;

// Where the segment [x0,y0] -> [x1,y1] first crosses the brick's box expanded
// by `pad` on every side (the ball's path relative to the brick + radius).
// Returns null when the segment never reaches the box. A sweep like this is
// what catches tunnelling: a fast ball can jump across a brick in one step
// without ever overlapping its end position.
function sweptEntry(x0, y0, x1, y1, brick, pad) {
  const minX = brick.x - pad;
  const maxX = brick.x + brick.w + pad;
  const minY = brick.y - pad;
  const maxY = brick.y + brick.h + pad;
  const dx = x1 - x0;
  const dy = y1 - y0;

  // Slab method: intersect the segment with each axis-aligned slab, keeping
  // the overlap of the two t-intervals.
  let tmin = 0;
  let tmax = 1;
  for (const axis of ['x', 'y']) {
    const d = axis === 'x' ? dx : dy;
    const p0 = axis === 'x' ? x0 : y0;
    const lo = axis === 'x' ? minX : minY;
    const hi = axis === 'x' ? maxX : maxY;
    if (d === 0) {
      // Movement parallel to the slab: only a point already inside it counts.
      if (p0 < lo || p0 > hi) return null;
    } else {
      let t1 = (lo - p0) / d;
      let t2 = (hi - p0) / d;
      if (t1 > t2) [t1, t2] = [t2, t1];
      tmin = Math.max(tmin, t1);
      tmax = Math.min(tmax, t2);
      if (tmin > tmax) return null;
    }
  }
  if (tmin > 1) return null;

  const t = Math.max(tmin, 0);
  return {
    t, // entry time in [0, 1] along the segment
    startedInside: tmin < 0, // the ball began this step already in the box
    x: x0 + dx * t,
    y: y0 + dy * t,
    minX,
    maxX,
    minY,
    maxY,
  };
}

// Resolves a bounce when the sweep is degenerate because the ball already
// overlaps the brick at the START of the step: the axis with the smaller
// penetration is the face that was hit, equal penetrations mean a corner.
// Also used for the push-out amount (which face the ball must leave by).
function resolvePenetration(ball, brick) {
  const penLeft = ball.x + ball.r - brick.x; // ball past the left edge
  const penRight = brick.x + brick.w - (ball.x - ball.r); // past the right
  const penTop = ball.y + ball.r - brick.y; // past the top edge
  const penBottom = brick.y + brick.h - (ball.y - ball.r); // past the bottom
  const penX = Math.min(penLeft, penRight);
  const penY = Math.min(penTop, penBottom);

  if (penX < penY) {
    // Side hit: flip vx only, leave vy alone.
    if (penLeft < penRight) {
      ball.vx = -Math.abs(ball.vx);
      ball.x = brick.x - ball.r - PUSH_OUT;
    } else {
      ball.vx = Math.abs(ball.vx);
      ball.x = brick.x + brick.w + ball.r + PUSH_OUT;
    }
  } else if (penY < penX) {
    // Top/bottom hit: flip vy only, leave vx alone.
    if (penTop < penBottom) {
      ball.vy = -Math.abs(ball.vy);
      ball.y = brick.y - ball.r - PUSH_OUT;
    } else {
      ball.vy = Math.abs(ball.vy);
      ball.y = brick.y + brick.h + ball.r + PUSH_OUT;
    }
  } else {
    // Corner: diagonal hit, flip both axes and push out on both.
    if (penLeft < penRight) {
      ball.vx = -Math.abs(ball.vx);
      ball.x = brick.x - ball.r - PUSH_OUT;
    } else {
      ball.vx = Math.abs(ball.vx);
      ball.x = brick.x + brick.w + ball.r + PUSH_OUT;
    }
    if (penTop < penBottom) {
      ball.vy = -Math.abs(ball.vy);
      ball.y = brick.y - ball.r - PUSH_OUT;
    } else {
      ball.vy = Math.abs(ball.vy);
      ball.y = brick.y + brick.h + ball.r + PUSH_OUT;
    }
  }
}

// Resolves the ball against every live brick for the move that just happened
// (from [prevX, prevY] to the ball's current position). Pure and testable;
// called by step() once per frame, instead of the old inline logic in frame().
//
// - Sweeps the path so a fast ball cannot tunnel through a brick.
// - Breaks every brick the ball touched in this pass (combo per brick).
// - Deflects the ball exactly ONCE, at the earliest contact: the grid gap is
//   8 px and the ball 14 px across, so a seam overlaps two bricks in the same
//   pass and a per-brick double flip would cancel out, letting the ball plow
//   through. Flip vy on a top/bottom hit, vx on a side hit, both on a corner.
// - Pushes the ball back out of the brick, or the overlap re-triggers the
//   bounce forever (sticky bounce).
//
// Returns the number of bricks destroyed.
export function brickHit(state, prevX, prevY) {
  const { ball, bricks } = state;

  // 1. Sweep the ball's path against every live brick.
  const hits = [];
  for (const brick of bricks) {
    if (!brick.alive) continue;
    const entry = sweptEntry(prevX, prevY, ball.x, ball.y, brick, ball.r);
    if (entry) hits.push({ brick, entry });
  }
  if (hits.length === 0) return 0;

  // 2. Break everything the ball touched, scoring per brick (combo grows
  //    within the pass, exactly like the old frame() loop did).
  for (const { brick } of hits) {
    brick.alive = false;
    state.combo += 1;
    state.score += scoreForBrick(brick, state.combo);
  }

  // 3. Deflect the ball once, at the earliest contact along the path.
  hits.sort((a, b) => a.entry.t - b.entry.t);
  const { brick, entry } = hits[0];

  if (entry.startedInside) {
    // Degenerate sweep (ball was already touching the brick at step start):
    // fall back to the shallowest-penetration face.
    resolvePenetration(ball, brick);
    return hits.length;
  }

  // The entry point lies on a face (or a corner) of the expanded box; the
  // epsilon handles float error in the slab division.
  const EPS = 0.001;
  const atLeft = Math.abs(entry.x - entry.minX) < EPS;
  const atRight = Math.abs(entry.x - entry.maxX) < EPS;
  const atTop = Math.abs(entry.y - entry.minY) < EPS;
  const atBottom = Math.abs(entry.y - entry.maxY) < EPS;

  if ((atTop || atBottom) && (atLeft || atRight)) {
    // Corner: diagonal hit, flip both components.
    ball.vy = atTop ? -Math.abs(ball.vy) : Math.abs(ball.vy);
    ball.vx = atLeft ? -Math.abs(ball.vx) : Math.abs(ball.vx);
    ball.y = atTop ? entry.minY - PUSH_OUT : entry.maxY + PUSH_OUT;
    ball.x = atLeft ? entry.minX - PUSH_OUT : entry.maxX + PUSH_OUT;
  } else if (atTop || atBottom) {
    // Top/bottom face: flip vy only, leave vx exactly as it was.
    ball.vy = atTop ? -Math.abs(ball.vy) : Math.abs(ball.vy);
    ball.y = atTop ? entry.minY - PUSH_OUT : entry.maxY + PUSH_OUT;
  } else {
    // Left/right face: flip vx only, leave vy exactly as it was.
    ball.vx = atLeft ? -Math.abs(ball.vx) : Math.abs(ball.vx);
    ball.x = atLeft ? entry.minX - PUSH_OUT : entry.maxX + PUSH_OUT;
  }

  return hits.length;
}

// --- Score & combo (NOT covered by tests — debt #5) ------------------------

// Combo multiplier. UNBOUNDED today: a long combo makes the score blow up
// uncontrollably (see #5, expected improvement = clamp it).
export function comboMultiplier(combo) {
  return 1 + combo * 0.5;
}

// Points earned for breaking a brick, combo included.
export function scoreForBrick(brick, combo) {
  return Math.round(brick.points * comboMultiplier(combo));
}

// --- Best score persistence ------------------------------------------------

// Reads the best score from a localStorage-compatible storage.
// Robust to corrupted or missing storage: returns 0 instead of throwing.
export function loadBest(storage) {
  if (!storage) return 0;
  try {
    const raw = storage.getItem(STORAGE_KEY);
    const value = Number.parseInt(raw, 10);
    return Number.isFinite(value) && value > 0 ? value : 0;
  } catch {
    return 0;
  }
}

// Writes the best score if the current score beats it. Returns the updated best.
export function saveBest(storage, score) {
  const best = loadBest(storage);
  if (score > best && storage) {
    try {
      storage.setItem(STORAGE_KEY, String(score));
    } catch {
      // storage unavailable (private mode, quota): silently ignore
    }
    return score;
  }
  return best;
}

// --- Physics (movement + wall/paddle/brick bounces) ------------------------

// Advances the ball by a time step `dt` (in seconds) and handles bounces off
// the walls, the ceiling, the paddle and the bricks.
// Returns `true` if the ball is lost (exits through the bottom).
export function step(state, dt) {
  const { ball, paddle } = state;

  const prevX = ball.x;
  const prevY = ball.y;

  ball.x += ball.vx * dt;
  ball.y += ball.vy * dt;

  // Side walls
  if (ball.x - ball.r < 0) {
    ball.x = ball.r;
    ball.vx = Math.abs(ball.vx);
  } else if (ball.x + ball.r > WIDTH) {
    ball.x = WIDTH - ball.r;
    ball.vx = -Math.abs(ball.vx);
  }

  // Ceiling
  if (ball.y - ball.r < 0) {
    ball.y = ball.r;
    ball.vy = Math.abs(ball.vy);
  }

  // Bricks: the path from the position at the start of this step is swept
  // against the grid, so the ball bounces off every face it crosses (and a
  // fast ball cannot tunnel through). Resolved BEFORE the paddle: the sweep
  // stops the ball at its earliest contact, so a ball that crosses the bricks
  // this step never reaches the paddle line at all.
  brickHit(state, prevX, prevY);

  // Paddle
  if (
    ball.vy > 0 &&
    ball.y + ball.r >= paddle.y &&
    ball.y + ball.r <= paddle.y + paddle.h &&
    ball.x >= paddle.x &&
    ball.x <= paddle.x + paddle.w
  ) {
    ball.y = paddle.y - ball.r;
    ball.vy = -Math.abs(ball.vy);
    // The rebound angle depends on where the paddle was hit.
    const hit = (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2);
    ball.vx = ballSpeed(state.level) * 0.6 * hit;
    state.combo = 0; // touching the paddle resets the combo
  }

  // Exit through the bottom: ball lost
  if (ball.y - ball.r > HEIGHT) {
    return true;
  }
  return false;
}

// --- Rendering (DOM) -------------------------------------------------------

// Main render loop. Pure drawing: all game logic (movement, bounces, brick
// destruction, score) lives in step()/brickHit(); this function only reads
// the state and paints it.
export function frame(ctx, state) {
  // Background
  ctx.fillStyle = palette.background;
  ctx.fillRect(0, 0, WIDTH, HEIGHT);

  // Bricks: drawing only — collision resolution happens in step() (#1).
  for (const brick of state.bricks) {
    if (!brick.alive) continue;
    ctx.fillStyle = brickColor(brick.row);
    ctx.fillRect(brick.x, brick.y, brick.w, brick.h);
  }

  // Paddle — color hard-coded instead of using the palette (inconsistency #6).
  ctx.fillStyle = '#00e5ff';
  ctx.fillRect(state.paddle.x, state.paddle.y, state.paddle.w, state.paddle.h);

  // Ball — also hard-coded (#6).
  ctx.fillStyle = '#39ff14';
  ctx.beginPath();
  ctx.arc(state.ball.x, state.ball.y, state.ball.r, 0, Math.PI * 2);
  ctx.fill();

  // HUD
  ctx.fillStyle = palette.text;
  ctx.font = '16px monospace';
  ctx.fillText(`Score ${state.score}`, 12, 24);
  ctx.fillText(`Best ${state.best}`, WIDTH - 110, 24);
  ctx.fillText(`Lives ${state.lives}`, WIDTH / 2 - 30, 24);
}

// --- Boot (browser entry point) --------------------------------------------

// Starts the game: wires up the canvas, the mouse and the animation loop.
// The only function that depends on the DOM; never called on import.
export function boot(doc = document) {
  const canvas = doc.getElementById('game');
  const ctx = canvas.getContext('2d');
  canvas.width = WIDTH;
  canvas.height = HEIGHT;

  const state = createState(1);
  state.best = loadBest(doc.defaultView?.localStorage ?? globalThis.localStorage);
  state.running = true;

  // Glow pass: a coarse offscreen light map, stretched over the field.
  const offscreen = doc.createElement('canvas');
  offscreen.width = GLOW_W;
  offscreen.height = GLOW_H;
  const glow = {
    map: createGlowMap(),
    image: offscreen.getContext('2d').createImageData(GLOW_W, GLOW_H),
  };

  // Move the paddle with the mouse.
  canvas.addEventListener('mousemove', (e) => {
    const rect = canvas.getBoundingClientRect();
    const x = e.clientX - rect.left - state.paddle.w / 2;
    state.paddle.x = Math.max(0, Math.min(WIDTH - state.paddle.w, x));
  });

  let last = performance.now();
  function loop(now) {
    const dt = Math.min((now - last) / 1000, 0.05);
    last = now;

    if (state.running) {
      const lost = step(state, dt);
      if (lost) {
        state.lives -= 1;
        state.combo = 0;
        if (state.lives <= 0) {
          state.best = saveBest(globalThis.localStorage, state.score);
          Object.assign(state, createState(state.level));
          state.best = loadBest(globalThis.localStorage);
        } else {
          // relaunch the ball
          state.ball = createState(state.level).ball;
        }
      }

      // Level cleared: all bricks broken
      if (state.bricks.every((b) => !b.alive)) {
        state.level += 1;
        state.bricks = makeBricks(state.level);
        state.ball = createState(state.level).ball;
      }
    }

    frame(ctx, state);
    drawGlow(ctx, glow, state, WIDTH, HEIGHT, offscreen);
    requestAnimationFrame(loop);
  }
  requestAnimationFrame(loop);

  return state;
}

